import json
import sys

data = json.load(sys.stdin)

# Let's find all elements that might contain ESF data
def find_esf(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_esf(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_esf(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'zloty' in obj.lower() or 'german' in obj.lower() or 'ESF' in obj:
            print(f'{path}: {obj[:200]}')

find_esf(data)
